const upsertPrinterProfile = `-- name: UpsertPrinterProfile :one
INSERT INTO printer_profiles (machine_id, enabled) VALUES ($1, $2)
ON CONFLICT (machine_id) DO UPDATE SET enabled=EXCLUDED.enabled, version=printer_profiles.version+1, updated_at=now()
WHERE printer_profiles.version=$3 OR $3=0
RETURNING machine_id, enabled, version, created_at, updated_at, identity_namespace, identity_value, model
`

type UpsertPrinterProfileParams struct {
	MachineID       uuid.UUID
	Enabled         bool
	ExpectedVersion int64
}

func (q *Queries) UpsertPrinterProfile(ctx context.Context, arg UpsertPrinterProfileParams) (PrinterProfile, error) {
	row := q.db.QueryRow(ctx, upsertPrinterProfile, arg.MachineID, arg.Enabled, arg.ExpectedVersion)
	var i PrinterProfile
	err := row.Scan(
		&i.MachineID,
		&i.Enabled,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.IdentityNamespace,
		&i.IdentityValue,
		&i.Model,
	)
	return i, err
}
